class MyLaw(Contract):
    VERSION = 1

    def __init__(self, num_agents, agent_names, *, prior_state=None):
        super().__init__(num_agents, agent_names, prior_state=prior_state)
        if prior_state is None:
            self.state = {
                "next_month_penalty": {name: 0.0 for name in agent_names},
                "last_reported_harvest": {name: 0.0 for name in agent_names},
            }
        else:
            self.state = prior_state
            if "next_month_penalty" not in self.state:
                self.state["next_month_penalty"] = {name: 0.0 for name in agent_names}
            if "last_reported_harvest" not in self.state:
                self.state["last_reported_harvest"] = {name: 0.0 for name in agent_names}
            for name in agent_names:
                self.state["next_month_penalty"].setdefault(name, 0.0)
                self.state["last_reported_harvest"].setdefault(name, 0.0)

    def on_round_start(self, month, fish_population, ctx) -> None:
        pass

    def resolve(self, month, fish_population, submissions, ctx) -> dict[str, float]:
        if fish_population < 5:
            base_limit = 0.0
        elif fish_population < 10:
            base_limit = 2.0
        else:
            base_limit = 3.0

        final_catches = {}
        for name in self.agent_names:
            requested = float(submissions.get(name, 0.0))
            penalty = float(self.state["next_month_penalty"].get(name, 0.0))
            allowed = max(0.0, base_limit - penalty)
            final_catches[name] = min(requested, allowed)

        return final_catches

    def on_round_end(self, month, fish_population_after, final_catches, ctx) -> None:
        new_penalties = {}
        for name in self.agent_names:
            caught = float(final_catches.get(name, 0.0))
            self.state["last_reported_harvest"][name] = caught
            if caught > 3.0:
                new_penalties[name] = 2.0
                ctx.sanction(name, 0.0, reason="Publicly named for breaking the conservation rule by harvesting more than 3 tons.")
            else:
                new_penalties[name] = 0.0
        self.state["next_month_penalty"] = new_penalties
